package org.freecad.mobilelab;
import java.util.*;
import org.json.*;

/** Exact native distance and pivot transforms, with pure arithmetic helpers for verification. */
final class PrecisionTools {
    static JSONObject object(int id)throws Exception{JSONArray a=new JSONArray(NativeCad.objects());for(int i=0;i<a.length();i++)if(a.getJSONObject(i).getInt("id")==id)return a.getJSONObject(i);throw new IllegalArgumentException("Select an existing object");}
    static double[] vector(JSONArray a)throws Exception{if(a==null||a.length()!=3)throw new IllegalArgumentException("Expected XYZ");return new double[]{a.getDouble(0),a.getDouble(1),a.getDouble(2)};}
    static double[] centre(JSONObject o)throws Exception{JSONArray b=o.getJSONArray("bbox");return new double[]{(b.getDouble(0)+b.getDouble(3))/2,(b.getDouble(1)+b.getDouble(4))/2,(b.getDouble(2)+b.getDouble(5))/2};}
    static double length(double x,double y,double z){return Math.hypot(Math.hypot(x,y),z);}
    static double angle(double[] p){if(p.length!=9)throw new IllegalArgumentException("Angle needs three XYZ points; the middle point is the vertex");double ax=p[0]-p[3],ay=p[1]-p[4],az=p[2]-p[5],bx=p[6]-p[3],by=p[7]-p[4],bz=p[8]-p[5],a=length(ax,ay,az),b=length(bx,by,bz);if(a<1e-9||b<1e-9)throw new IllegalArgumentException("Angle points must be distinct");return Math.toDegrees(Math.acos(Math.max(-1,Math.min(1,(ax/a)*(bx/b)+(ay/a)*(by/b)+(az/a)*(bz/b)))));}
    static double[] matrix(double ax,double ay,double az,double degrees){double length=length(ax,ay,az);if(!Double.isFinite(length)||length<1e-12||!Double.isFinite(degrees)||Math.abs(degrees)>1000000)throw new IllegalArgumentException("Enter a non-zero axis and finite angle within +/- 1,000,000 degrees");ax/=length;ay/=length;az/=length;double a=Math.toRadians(degrees%360),c=Math.cos(a),s=Math.sin(a),t=1-c;return new double[]{t*ax*ax+c,t*ax*ay-s*az,t*ax*az+s*ay,t*ax*ay+s*az,t*ay*ay+c,t*ay*az-s*ax,t*ax*az-s*ay,t*ay*az+s*ax,t*az*az+c};}
    static double[] apply(double[] m,double[] v){return new double[]{m[0]*v[0]+m[1]*v[1]+m[2]*v[2],m[3]*v[0]+m[4]*v[1]+m[5]*v[2],m[6]*v[0]+m[7]*v[1]+m[8]*v[2]};}
    // Native rotation order is Rz * Ry * Rx; its pivot is the current bounding-box centre.
    static double[] euler(double[] m){double y=Math.asin(Math.max(-1,Math.min(1,-m[6]))),x,z;if(Math.abs(Math.cos(y))>1e-8){x=Math.atan2(m[7],m[8]);z=Math.atan2(m[3],m[0]);}else{x=0;z=Math.atan2(-m[1],m[4]);}return new double[]{Math.toDegrees(x),Math.toDegrees(y),Math.toDegrees(z)};}
    static void rotateAround(int id,double[] p)throws Exception{if(p.length!=7)throw new IllegalArgumentException("RotateAround pivotXYZ axisXYZ angleDegrees");JSONObject o=object(id);double[] c=centre(o),xyz=vector(o.getJSONArray("xyz")),m=matrix(p[3],p[4],p[5],p[6]),e=euler(m),v=apply(m,new double[]{c[0]-p[0],c[1]-p[1],c[2]-p[2]});NativeCad.rotate(id,e[0],e[1],e[2]);NativeCad.move(id,xyz[0]+p[0]+v[0]-c[0],xyz[1]+p[1]+v[1]-c[1],xyz[2]+p[2]+v[2]-c[2]);FeatureModel.detach(id);FeatureModel.recompute(id);}
    static void scaleAround(int id,double[] p)throws Exception{if(p.length!=4||p[3]<.0001||p[3]>1000)throw new IllegalArgumentException("ScaleAround pivotXYZ factor (0.0001 to 1000)");JSONObject o=object(id);double[] c=centre(o);NativeCad.scale(id,p[3]);double[] xyz=vector(object(id).getJSONArray("xyz"));NativeCad.move(id,xyz[0]+(c[0]-p[0])*(p[3]-1),xyz[1]+(c[1]-p[1])*(p[3]-1),xyz[2]+(c[2]-p[2])*(p[3]-1));FeatureModel.detach(id);FeatureModel.recompute(id);}
    static int identifier(String text){double x=Expressions.evaluate(text);if(x<1||x>Integer.MAX_VALUE||x!=Math.rint(x))throw new IllegalArgumentException("Expected a positive object ID");return (int)x;}
    static void align(int source,int target,String axis,String sourceAnchor,String targetAnchor)throws Exception{if(source==target)throw new IllegalArgumentException("Choose two different objects");int index="XYZ".indexOf(axis.toUpperCase(Locale.US));if(axis.length()!=1||index<0)throw new IllegalArgumentException("Axis must be X, Y or Z");FeatureModel.independent(new int[]{source,target});JSONObject a=object(source),b=object(target);double delta=anchor(b.getJSONArray("bbox"),index,targetAnchor)-anchor(a.getJSONArray("bbox"),index,sourceAnchor);double[] xyz=vector(a.getJSONArray("xyz"));xyz[index]+=delta;FeatureModel.move(source,xyz[0],xyz[1],xyz[2]);}
    static double anchor(JSONArray bounds,int axis,String mode)throws Exception{switch(mode.toLowerCase(Locale.US)){case "min":return bounds.getDouble(axis);case "max":return bounds.getDouble(axis+3);case "centre":case "center":return (bounds.getDouble(axis)+bounds.getDouble(axis+3))/2;default:throw new IllegalArgumentException("Anchor must be Min, Centre or Max");}}
    static String measure(int selected,List<String> args)throws Exception{
        if(args.isEmpty()){JSONObject o=object(selected),a=new JSONObject(NativeCad.analyze(selected,3));return "Object #"+selected+"\nBounds (mm): "+o.getJSONArray("bounds")+"\nBounding-box centre (mm): "+new JSONArray(centre(o))+"\nVolume (mm³): "+a.optDouble("volume")+"\nSurface area (mm²): "+a.optDouble("area")+"\nTotal edge length (mm): "+a.optDouble("length")+"\n\nUse Measure id1 id2 for exact CAD minimum distance; Distance XYZ XYZ; Angle XYZ XYZ XYZ. Mesh distance is not supported.";}
        if(args.size()!=2)throw new IllegalArgumentException("Measure [firstId secondId]");int first=identifier(args.get(0)),second=identifier(args.get(1));if(first==second)throw new IllegalArgumentException("Choose two different objects");if(object(first).getBoolean("mesh")||object(second).getBoolean("mesh"))throw new IllegalArgumentException("Minimum distance requires exact CAD objects");return String.format(Locale.US,"Minimum CAD distance #%d → #%d: %.8f mm",first,second,NativeCad.distance(first,second));
    }
}
